<template><section class="letterheads"><header><div><h2>{{ t('libresign','Letterheads') }}</h2><p>{{ t('libresign','Create a branded document, review its fit, and obtain approval before external signing.') }}</p></div><div class="actions"><NcButton v-if="canCreate" variant="primary" @click="start">{{ t('libresign','New Document') }}</NcButton><NcButton :disabled="busy" @click="refresh">{{ t('libresign','Refresh') }}</NcButton></div></header>
<div v-if="error" class="alert" role="alert"><strong>{{ error }}</strong></div><p v-if="notice" class="notice" role="status">{{ notice }}</p>
<div v-if="!selected&&!creating" class="view-options"><NcButton :aria-pressed="view==='mine'" @click="changeView('mine')">{{ t('libresign','My Documents') }}</NcButton><NcButton v-if="canApprove" :aria-pressed="view==='approvals'" @click="changeView('approvals')">{{ t('libresign','Assigned Approvals') }}</NcButton><NcButton v-if="isAdmin" :aria-pressed="view==='all'" @click="changeView('all')">{{ t('libresign','All Documents') }}</NcButton></div>
<form v-if="creating" class="panel" @submit.prevent="create"><h3>{{ t('libresign','Prepare letterheaded document') }}</h3><div class="grid"><label>{{ t('libresign','Document name') }}<input v-model="draft.name" maxlength="200" required></label><label>{{ t('libresign','Shared letterhead') }}<select v-model.number="draft.templateId" required><option :value="0" disabled>{{ t('libresign','Choose a letterhead') }}</option><option v-for="head in templates.filter(h=>Number(h.active))" :key="head.id" :value="head.id">{{ head.name }}</option></select></label><div class="upload-field"><span>{{ t('libresign','Upload Document') }}</span><FilePicker :key="uploadKey" :label="t('libresign','Upload Document')" :filename="documentFilename" :hint="t('libresign','PDF · Up to 20 MB')" accept="application/pdf,.pdf" :disabled="busy" required @change="uploadDocument" /></div><label>{{ t('libresign','Letterhead layer') }}<select v-model="draft.layer"><option value="front">{{ t('libresign','In front of content') }}</option><option value="behind">{{ t('libresign','Behind content') }}</option></select></label></div><p class="hint">{{ t('libresign','Upload an unsigned PDF with space for the letterhead. The letterhead is fitted proportionally to every page; your document is not reflowed. A preview is available before submitting for approval.') }}</p>
<h3>{{ t('libresign','Signers') }}</h3><CampaignRecipientPicker api-base="letterhead" :disabled="busy" :existing="draft.recipients" @add="addRecipient" /><ol class="signer-list"><li v-for="(r,index) in draft.recipients" :key="r.uid||r.email"><span><strong>{{ r.name }}</strong> · {{ r.email }}<small>{{ r.uid ? t('libresign','Internal') : t('libresign','External') }}</small></span><NcButton @click="draft.recipients.splice(index,1)">{{ t('libresign','Remove') }}</NcButton></li></ol><p class="hint">{{ t('libresign','Signers are invited in the order listed. Recipients are fixed once this document is prepared; changing them requires a new document and approval.') }}</p>
<div v-if="hasExternal" class="approval-choice"><h3>{{ t('libresign','External signing requires approval') }}</h3><label>{{ t('libresign','Choose a Letterhead Document Approver') }}<NcSelect v-model="chosenApprover" :options="approvers" label="name" track-by="uid" :searchable="true" :clearable="true" :filterable="false" :placeholder="t('libresign','Search approvers')" @search="searchApprovers" /></label><p>{{ t('libresign','The selected approver reviews this exact letterhead, content and recipient list. Signing invitations and PDF download remain unavailable until approval.') }}</p></div><div class="actions"><NcButton @click="creating=false">{{ t('libresign','Cancel') }}</NcButton><NcButton type="submit" variant="primary" :disabled="busy||!draft.pdf||!draft.templateId||!draft.recipients.length||(hasExternal&&!chosenApprover)">{{ t('libresign','Create preview') }}</NcButton></div></form>
<section v-if="selected" class="panel"><div class="detail-heading"><div><h3>{{ selected.name }}</h3><p><strong>{{ stateLabel(selected.state) }}</strong> · {{ selected.owner.name }} · {{ campaignDate(selected.createdAt) }}</p></div><NcButton @click="closeDocument">{{ t('libresign','Back to documents') }}</NcButton></div><div v-if="selected.state!=='approved'" class="notice"><strong>{{ t('libresign','Preview only · PDF download and signing are locked') }}</strong><p>{{ t('libresign','Check every page before submitting or approving. A visible preview can still be captured or printed by the device.') }}</p></div><p v-if="selected.notificationWarning" class="alert" role="alert">{{ selected.notificationWarning }}</p><p v-if="selected.approver">{{ t('libresign','Selected approver') }}: {{ selected.approver.name }}</p><p v-if="selected.reason"><strong>{{ t('libresign','Approval comments') }}:</strong> {{ selected.reason }}</p><details><summary>{{ t('libresign','Approved recipient list') }}</summary><ol><li v-for="r in selected.recipients" :key="r.email">{{ r.name }} · {{ r.email }} · {{ r.uid ? t('libresign','Internal') : t('libresign','External') }}</li></ol></details>
<div class="preview-toolbar"><NcButton :disabled="previewPage<=1" @click="previewPage--">{{ t('libresign','Previous page') }}</NcButton><span>{{ previewPage }} / {{ selected.pages }}</span><NcButton :disabled="previewPage>=selected.pages" @click="previewPage++">{{ t('libresign','Next page') }}</NcButton></div><div class="preview"><img :key="selected.id+'-'+previewPage" :src="campaignUrl('letterhead/documents/'+selected.id+'/preview/'+previewPage)" :alt="t('libresign','Letterheaded document preview')"></div>
<div v-if="selected.owner.uid===currentUid&&selected.state==='draft'" class="actions"><NcButton variant="primary" :disabled="busy" @click="submit">{{ t('libresign','Submit for approval') }}</NcButton></div>
<div v-if="canApprove&&selected.approver?.uid===currentUid&&selected.state==='pending'" class="approval-decision"><h3>{{ t('libresign','Review decision') }}</h3><label>{{ t('libresign','Comments (required when rejecting)') }}<textarea v-model="reason" maxlength="2000" rows="3" /></label><div class="actions"><NcButton :disabled="busy||!reason.trim()" @click="decide(false)">{{ t('libresign','Reject') }}</NcButton><NcButton variant="primary" :disabled="busy" @click="decide(true)">{{ t('libresign','Approve this document') }}</NcButton></div></div>
<div v-if="selected.state==='approved'" class="actions"><a :href="campaignUrl('letterhead/documents/'+selected.id+'/download')">{{ t('libresign','Download approved PDF') }}</a><NcButton v-if="selected.owner.uid===currentUid&&!signingOpen&&!selected.fileId" variant="primary" :disabled="busy" @click="signingOpen=true">{{ t('libresign','Place fields and request signatures') }}</NcButton></div><p v-if="selected.state==='approved'" class="hint">{{ t('libresign','Approval does not send invitations. Set up fields and send the request below when you are ready.') }}</p><LetterheadSigning v-if="selected.state==='approved'&&selected.owner.uid===currentUid&&(signingOpen||selected.fileId)" :key="selected.id" :document-id="selected.id" @prepared="selected.fileId=$event" />
<details v-if="selected.events?.length"><summary>{{ t('libresign','Approval history') }}</summary><ol><li v-for="event in selected.events" :key="event.id">{{ event.action }} · {{ event.actor }} · {{ campaignDate(Number(event.created_at)) }}</li></ol></details></section>
<template v-if="!creating&&!selected"><div class="table-scroll"><table><thead><tr><th>{{ t('libresign','Document') }}</th><th>{{ t('libresign','Creator') }}</th><th>{{ t('libresign','Status') }}</th><th>{{ t('libresign','Date Created') }}</th><th>{{ t('libresign','Approver') }}</th></tr></thead><tbody><tr v-for="doc in documents" :key="doc.id"><td><button class="link" @click="open(doc.id)">{{ doc.name }}</button></td><td>{{ doc.owner.name }}</td><td>{{ stateLabel(doc.state) }}</td><td>{{ campaignDate(doc.createdAt) }}</td><td>{{ doc.approver?.name || '—' }}</td></tr><tr v-if="!documents.length"><td colspan="5">{{ t('libresign','No documents in this view.') }}</td></tr></tbody></table></div><div class="actions pagination"><NcButton :disabled="busy||page<=1" @click="changePage(-1)">{{ t('libresign','Previous') }}</NcButton><span>{{ page }} / {{ Math.max(1,Math.ceil(total/25)) }}</span><NcButton :disabled="busy||page*25>=total" @click="changePage(1)">{{ t('libresign','Next') }}</NcButton></div></template>
<details v-if="isAdmin&&!creating&&!selected" class="panel"><summary>{{ t('libresign','Manage shared letterheads') }}</summary><p>{{ t('libresign','Upload a one-page PDF containing your header, footer and branding. All staff can reuse active templates. Add approvers to the Nextcloud group Letterhead Document Approver.') }}</p><form @submit.prevent="addTemplate"><div class="grid"><label>{{ t('libresign','Template name') }}<input v-model="templateName" maxlength="200" required></label><div class="upload-field"><span>{{ t('libresign','One-page letterhead PDF') }}</span><FilePicker :key="templateUploadKey" :label="t('libresign','One-page letterhead PDF')" :filename="templateFilename" :hint="t('libresign','One-page PDF · Up to 20 MB')" accept="application/pdf,.pdf" :disabled="busy" required @change="uploadTemplate" /></div></div><NcButton type="submit" :disabled="busy||!templatePdf||!templateName.trim()">{{ t('libresign','Add shared letterhead') }}</NcButton></form><ul class="signer-list"><li v-for="head in templates" :key="head.id"><span>{{ head.name }} · {{ Number(head.active) ? t('libresign','Active') : t('libresign','Inactive') }}</span><NcButton :disabled="busy" @click="toggleTemplate(head)">{{ Number(head.active) ? t('libresign','Deactivate') : t('libresign','Activate') }}</NcButton></li></ul></details>
</section></template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {useRoute} from 'vue-router'
import {getCurrentUser} from '@nextcloud/auth'
import {confirmPassword} from '@nextcloud/password-confirmation'
import {t} from '@nextcloud/l10n'
import NcButton from '@nextcloud/vue/components/NcButton'
import NcSelect from '@nextcloud/vue/components/NcSelect'
import CampaignRecipientPicker from '../components/Request/CampaignRecipientPicker.vue'
import {campaignGet,campaignPost,campaignUrl,campaignDate,campaignError,mergeCampaignRecipients,type CampaignRecipient} from '../services/campaigns'
import FilePicker from '../components/FilePicker.vue'
import LetterheadSigning from '../components/Letterheads/LetterheadSigning.vue'
type Person={uid:string,name:string,email?:string};type Template={id:number,name:string,active:number|boolean};type Doc={fileId?:number|null,id:number,name:string,state:string,revision:number,owner:Person,approver:Person|null,createdAt:number,approvedAt:number|null,recipients:CampaignRecipient[],pages:number,reason:string,notificationWarning?:string,events?:Array<{id:number,action:string,actor:string,created_at:number}>}
const signingOpen=ref(false),documentFilename=ref(''),templateFilename=ref(''),uploadKey=ref(0),templateUploadKey=ref(0)
const route=useRoute(),currentUid=getCurrentUser()?.uid||'',busy=ref(false),error=ref(''),notice=ref(''),creating=ref(false),selected=ref<Doc|null>(null),documents=ref<Doc[]>([]),templates=ref<Template[]>([]),isAdmin=ref(false),canApprove=ref(false),canCreate=ref(false),view=ref('mine'),page=ref(1),total=ref(0),previewPage=ref(1),reason=ref(''),approvers=ref<Person[]>([]),chosenApprover=ref<Person|null>(null),templateName=ref(''),templatePdf=ref('')
const blank=()=>({name:'',templateId:0,pdf:'',layer:'front',recipients:[] as CampaignRecipient[]}),draft=reactive(blank()),hasExternal=computed(()=>draft.recipients.some(r=>!r.uid))
async function perform(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){error.value=campaignError(e)}finally{busy.value=false}}
async function load(){const result=await campaignGet<{data:Doc[],total:number,isAdmin:boolean,canApprove:boolean,canCreate:boolean}>('letterhead/documents',{page:page.value,view:view.value});documents.value=result.data;total.value=result.total;isAdmin.value=result.isAdmin;canApprove.value=result.canApprove;canCreate.value=result.canCreate;templates.value=await campaignGet<Template[]>('letterheads')}
async function refresh(){await perform(async()=>{if(selected.value)selected.value=await campaignGet<Doc>('letterhead/documents/'+selected.value.id);else await load()})}
function closeDocument(){selected.value=null;signingOpen.value=false}
function start(){closeDocument();documentFilename.value='';uploadKey.value++;creating.value=true;Object.assign(draft,blank());chosenApprover.value=null;error.value='';notice.value='';void searchApprovers('')}
async function searchApprovers(search:string){try{approvers.value=await campaignGet<Person[]>('letterhead/users',{search,approvers:true})}catch(e){error.value=campaignError(e)}}
async function read(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return '';if(!file.name.toLowerCase().endsWith('.pdf')||file.size>20*1024*1024)throw {response:{data:{message:'Choose a PDF no larger than 20 MB.'}}};return await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)})}
async function uploadDocument(e:Event){await perform(async()=>{draft.pdf='';documentFilename.value='';draft.pdf=await read(e);documentFilename.value=(e.target as HTMLInputElement).files?.[0]?.name||''})}async function uploadTemplate(e:Event){await perform(async()=>{templatePdf.value='';templateFilename.value='';templatePdf.value=await read(e);templateFilename.value=(e.target as HTMLInputElement).files?.[0]?.name||''})}
function addRecipient(r:CampaignRecipient){draft.recipients=mergeCampaignRecipients(draft.recipients,[r]).recipients}
async function create(){await perform(async()=>{selected.value=await campaignPost<Doc>('letterhead/documents',{document:{...draft,approverUid:chosenApprover.value?.uid||null}});creating.value=false;previewPage.value=1})}
async function open(id:number){await perform(async()=>{signingOpen.value=false;selected.value=await campaignGet<Doc>('letterhead/documents/'+id);previewPage.value=1;reason.value=''})}
async function submit(){await perform(async()=>{if(selected.value)selected.value=await campaignPost<Doc>('letterhead/documents/'+selected.value.id+'/submit',{revision:selected.value.revision})})}
async function decide(approve:boolean){await perform(async()=>{if(selected.value)selected.value=await campaignPost<Doc>('letterhead/documents/'+selected.value.id+'/decision',{revision:selected.value.revision,approve,reason:reason.value})})}
async function addTemplate(){await perform(async()=>{await confirmPassword();await campaignPost('letterheads',{name:templateName.value,pdf:templatePdf.value});templateName.value='';templatePdf.value='';templateFilename.value='';templateUploadKey.value++;await load();notice.value=t('libresign','Shared letterhead added.')})}
async function toggleTemplate(head:Template){await perform(async()=>{await confirmPassword();await campaignPost('letterheads/'+head.id+'/state',{active:!Number(head.active)});await load()})}
async function changeView(next:string){view.value=next;page.value=1;await perform(load)}async function changePage(delta:number){page.value+=delta;await perform(load)}
function stateLabel(state:string){return ({draft:t('libresign','Preview · not submitted'),pending:t('libresign','Awaiting approval'),approved:t('libresign','Approved for release'),rejected:t('libresign','Rejected')} as Record<string,string>)[state]||state}
onMounted(()=>perform(async()=>{await load();const id=Number(route.query.document);if(Number.isInteger(id)&&id>0){selected.value=await campaignGet<Doc>('letterhead/documents/'+id);previewPage.value=1}else if(route.query.new==='1'&&canCreate.value)start()}))
</script>
<style scoped lang="scss">
.letterheads{padding:32px clamp(14px,3vw,48px);width:100%;box-sizing:border-box;overflow-y:auto}header,.detail-heading{display:flex;justify-content:space-between;align-items:start;gap:20px;flex-wrap:wrap;margin-bottom:24px}h2{font-size:28px;font-weight:650;margin-bottom:8px}h3{font-size:20px;font-weight:650;margin-block:8px 18px}p{line-height:1.6;margin-block:10px 16px}.actions,.view-options{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.view-options{margin-bottom:22px}.panel{padding:24px;border:1px solid var(--color-border);border-radius:16px;margin-block:20px}.upload-field{display:flex;flex-direction:column;gap:7px;margin-block:10px;min-width:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}label{display:flex;flex-direction:column;gap:7px;margin-block:10px}input,select,textarea{box-sizing:border-box;width:100%;min-height:44px;margin:0}.hint{color:var(--color-text-maxcontrast);font-size:14px}.signer-list{padding:0;list-style:none;margin-block:16px}.signer-list li{display:flex;justify-content:space-between;align-items:center;gap:12px;border-bottom:1px solid var(--color-border);padding:12px}.signer-list small{display:block;color:var(--color-text-maxcontrast)}.approval-choice,.approval-decision{padding:20px;border:1px solid var(--color-primary-element);border-radius:12px;margin-block:20px;background:var(--color-primary-element-light)}.preview-toolbar{display:flex;justify-content:space-between;align-items:center;margin-block:20px}.preview{padding:10px;background:var(--color-background-dark);text-align:center;border:1px solid var(--color-border);margin-bottom:22px}.preview img{display:block;width:auto;max-width:100%;height:auto;margin:auto;background:white}.alert,.notice{padding:16px 20px;border-inline-start:5px solid var(--color-primary-element);border-radius:8px;background:var(--color-background-dark);margin-bottom:18px}.alert{border-color:var(--color-error)}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{text-align:start;padding:15px;border-bottom:1px solid var(--color-border)}th{background:var(--color-background-hover)}.link{background:none;border:0;text-decoration:underline;color:var(--color-primary-element);padding:0;text-align:start}.pagination{justify-content:space-between;margin-top:20px}summary{font-weight:650;cursor:pointer}.actions a{color:var(--color-primary-element);text-decoration:underline;padding:10px}@media(max-width:767px){.letterheads{padding:20px 12px}.panel{padding:16px 12px}.grid{grid-template-columns:1fr}input,select,textarea{font-size:16px}}
</style>
